CREATE TABLE IF NOT EXISTS member_quizzes(id bigserial PRIMARY KEY,lesson_id bigint NOT NULL UNIQUE REFERENCES member_lessons(id) ON DELETE CASCADE,title text NOT NULL,pass_score integer NOT NULL CHECK(pass_score BETWEEN 0 AND 100),max_attempts integer NOT NULL CHECK(max_attempts BETWEEN 1 AND 20),show_explanations boolean NOT NULL DEFAULT true,enabled boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS member_quiz_questions(id bigserial PRIMARY KEY,quiz_id bigint NOT NULL REFERENCES member_quizzes(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN('multiple_choice','true_false')),prompt text NOT NULL,options jsonb NOT NULL,correct_answer text NOT NULL,explanation text NOT NULL DEFAULT '',sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS member_quiz_attempts(id bigserial PRIMARY KEY,quiz_id bigint NOT NULL REFERENCES member_quizzes(id),member_id bigint NOT NULL REFERENCES member_accounts(id),answers jsonb NOT NULL,score integer NOT NULL,passed boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS member_quiz_attempts_member ON member_quiz_attempts(member_id,quiz_id,created_at);
